insert into conversations (clinic_id, patient_id, elevenlabs_conversation_id, channel, direction, started_at, duration_secs, status, title, summary, intent, outcome, call_successful, transcript, analysis) values ('00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-0000000000c2', 'conv_video_jorge', 'whatsapp', 'entrante', '2026-10-25 07:12-03', 190, 'done', 'Turno de control y pedido de receta', 'Jorge Pérez reservó el control de traumatología con la Dra. Fernández para el lunes 26 a las 9:40 y pidió renovar la receta del antiinflamatorio. Se creó la tarea para la doctora.', 'turno_nuevo', 'reservado', 'success', '[{"role": "user", "message": "🎤 Audio: «Hola Sofi, buen día. Quería sacar un turno con la traumatóloga, y de paso necesito que me renueven una receta.»"}, {"role": "agent", "message": "¡Hola, Jorge! Te ayudo con las dos cosas. Para el control de la rodilla con la Dra. Fernández tengo el lunes 26 a las 9:40 o el miércoles 28 a las 11:00. ¿Cuál preferís?"}, {"role": "user", "message": "Lunes 9:40"}, {"role": "agent", "message": "Listo, reservado: lunes 26 a las 9:40 con la Dra. Fernández, en Av. Santa Fe 3200, 4º piso. Traé la credencial de Swiss Medical. La receta ya se la pedí a la doctora: te llega por acá en 48 h hábiles."}]'::jsonb, '{"sentimiento": "positivo"}'::jsonb);
insert into conversations (clinic_id, patient_id, elevenlabs_conversation_id, channel, direction, started_at, duration_secs, status, title, summary, intent, outcome, call_successful, transcript, analysis) values ('00000000-0000-4000-8000-000000000001', '00000000-0000-4000-8000-100000000000', 'conv_video_2', 'telefono', 'entrante', '2026-10-25 06:41-03', 132, 'done', 'Consulta por un lunar', 'Carolina pidió revisar un lunar que cambió de color. Se le dio turno con el Dr. Gómez el martes 27 a las 15:20.', 'turno_nuevo', 'reservado', 'success', '[{"role": "agent", "message": "Centro Médico Plaza, buen día. Te atiende Sofi."}, {"role": "user", "message": "Hola, quería que me vean un lunar."}]'::jsonb, '{"sentimiento": "positivo"}'::jsonb);
